const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money = value => new Intl.NumberFormat('tr-TR', {style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(value || 0));
const dateText = value => value ? new Date(String(value).length === 10 ? `${value}T12:00:00` : value).toLocaleDateString('tr-TR',{day:'2-digit',month:'short',year:'numeric'}) : '—';
const timeText = value => value ? new Date(value).toLocaleString('tr-TR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '—';
const localDate = (offset = 0) => { const d = new Date(); d.setDate(d.getDate()+offset); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
